package com.university.learning.service;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.web.server.ResponseStatusException;
import java.util.UUID;
import static org.junit.jupiter.api.Assertions.*;
class AdaptivePlanServiceTest {
 ObjectMapper mapper=new ObjectMapper(); JdbcTemplate jdbc; AdaptivePlanService s;
 @BeforeEach void setup(){jdbc=new JdbcTemplate(new DriverManagerDataSource("jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;DB_CLOSE_DELAY=-1","sa",""));s=new AdaptivePlanService(jdbc,mapper);}
 JsonNode body(String s)throws Exception{return mapper.readTree(s);}
 ObjectNode create()throws Exception{return s.create(1,body("{\"title\":\"数据库\",\"goal\":\"掌握事务\",\"dailyMinutes\":30,\"modules\":[{\"title\":\"隔离级别\",\"tasks\":[{\"title\":\"幻读例子\",\"minutes\":45},{\"title\":\"总结\",\"minutes\":15}]}]}"));}
 String id(ObjectNode p){return p.path("id").asText();}String task(ObjectNode p){return p.path("modules").get(0).path("tasks").get(0).path("id").asText();}
 @Test void durableAndOwned()throws Exception{var p=create();assertEquals(p,new AdaptivePlanService(jdbc,mapper).get(1,id(p)));assertTrue(s.list(2).isEmpty());assertEquals(404,assertThrows(ResponseStatusException.class,()->s.get(2,id(p))).getStatusCode().value());}
 @Test void proposalDoesNotMutateAndSplitConservesEffort()throws Exception{var p=create();var pr=s.propose(1,id(p),body("{\"version\":1,\"message\":\"每天只有20分钟\"}"));assertEquals(p,s.get(1,id(p)));assertEquals(3,pr.path("proposedPlan").path("nextTasks").size());var saved=s.apply(1,id(p),pr.path("id").asText(),body("{\"version\":1}"));assertEquals(2,saved.path("version").asInt());int sum=0;for(var t:saved.path("modules").get(0).path("tasks"))sum+=t.path("minutes").asInt();assertEquals(60,sum);assertTrue(saved.path("canUndo").asBoolean());}
 @Test void completedAndCheckpointPreserved()throws Exception{var p=create();s.updateTask(1,id(p),task(p),body("{\"version\":1,\"status\":\"completed\",\"checkpoint\":\"看完例子\"}"));var pr=s.propose(1,id(p),body("{\"version\":2,\"message\":\"每天10分钟\"}"));var t=pr.path("proposedPlan").path("modules").get(0).path("tasks").get(0);assertEquals("completed",t.path("status").asText());assertEquals(45,t.path("minutes").asInt());assertEquals("看完例子",t.path("checkpoint").asText());}
 @Test void pauseResumeAndStaleProtection()throws Exception{var p=create();s.updateTask(1,id(p),task(p),body("{\"version\":1,\"status\":\"paused\",\"checkpoint\":\"第三页\",\"nextAction\":\"继续例子\"}"));assertEquals(409,assertThrows(ResponseStatusException.class,()->s.updateTask(1,id(p),task(p),body("{\"version\":1,\"status\":\"completed\"}"))).getStatusCode().value());var resumed=s.updateTask(1,id(p),task(p),body("{\"version\":2,\"status\":\"in_progress\"}"));assertEquals("第三页",resumed.path("nextTasks").get(0).path("checkpoint").asText());}
 @Test void undoRestoresButCannotEraseNewProgress()throws Exception{var p=create();var pr=s.propose(1,id(p),body("{\"version\":1,\"message\":\"每天20分钟\"}"));s.apply(1,id(p),pr.path("id").asText(),body("{\"version\":1}"));var undone=s.undo(1,id(p),body("{\"version\":2}"));assertEquals(2,undone.path("modules").get(0).path("tasks").size());pr=s.propose(1,id(p),body("{\"version\":3,\"message\":\"每天20分钟\"}"));s.apply(1,id(p),pr.path("id").asText(),body("{\"version\":3}"));s.updateTask(1,id(p),task(p),body("{\"version\":4,\"status\":\"completed\"}"));assertThrows(ResponseStatusException.class,()->s.undo(1,id(p),body("{\"version\":5}")));}
 @Test void deadlineRequiresExplicitChoice()throws Exception{var p=create();var pr=s.propose(1,id(p),body("{\"version\":1,\"message\":\"每天20分钟\",\"deadline\":\"2000-01-01\"}"));assertFalse(pr.path("conflict").isNull());assertThrows(ResponseStatusException.class,()->s.apply(1,id(p),pr.path("id").asText(),body("{\"version\":1}")));var saved=s.apply(1,id(p),pr.path("id").asText(),body("{\"version\":1,\"resolution\":\"defer\"}"));assertEquals(0,saved.path("nextTasks").size());assertFalse(saved.path("modules").get(0).path("tasks").isEmpty());}
 @Test void extensionAndProposalOwnership()throws Exception{var p=create();var pr=s.propose(1,id(p),body("{\"version\":1,\"message\":\"每天20分钟\",\"deadline\":\"2000-01-01\"}"));assertThrows(ResponseStatusException.class,()->s.apply(2,id(p),pr.path("id").asText(),body("{\"version\":1,\"resolution\":\"extend\"}")));assertNotEquals("2000-01-01",s.apply(1,id(p),pr.path("id").asText(),body("{\"version\":1,\"resolution\":\"extend\"}")).path("deadline").asText());}
 @Test void invalidInputsFail()throws Exception{assertThrows(ResponseStatusException.class,()->s.create(1,body("{}")));var p=create();assertThrows(ResponseStatusException.class,()->s.propose(1,id(p),body("{\"version\":1,\"message\":\"更改\",\"dailyMinutes\":0}")));assertThrows(ResponseStatusException.class,()->s.updateTask(1,id(p),task(p),body("{\"version\":1,\"status\":\"mastered\"}")));assertThrows(ResponseStatusException.class,()->s.propose(1,id(p),body("{\"version\":1,\"message\":\"更改\",\"deadline\":\"wrong\"}")));}

 @Test void overflowAndUnsupportedMessagesRejected()throws Exception{var p=create();assertThrows(ResponseStatusException.class,()->s.propose(1,id(p),body("{\"version\":1,\"message\":\"调整\",\"dailyMinutes\":4294967297}")));assertThrows(ResponseStatusException.class,()->s.propose(1,id(p),body("{\"version\":1,\"message\":\"把月亮变蓝\"}")));}
 @Test void savedProgressInvalidatesProposal()throws Exception{var p=create();var pr=s.propose(1,id(p),body("{\"version\":1,\"message\":\"每天20分钟\"}"));s.updateTask(1,id(p),task(p),body("{\"version\":1,\"status\":\"completed\"}"));assertEquals(409,assertThrows(ResponseStatusException.class,()->s.apply(1,id(p),pr.path("id").asText(),body("{\"version\":2}"))).getStatusCode().value());}
 @Test void databaseConnectionReopenPreservesPlan()throws Exception{String url="jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;DB_CLOSE_DELAY=-1";var ds=new DriverManagerDataSource(url,"sa","");var first=new AdaptivePlanService(new JdbcTemplate(ds),mapper);var p=first.create(1,body("{\"title\":\"复习\",\"goal\":\"数据库\",\"modules\":[{\"title\":\"事务\",\"tasks\":[{\"title\":\"例子\",\"minutes\":20}]}]}"));try(var c=ds.getConnection()){assertFalse(c.isClosed());}var reopened=new AdaptivePlanService(new JdbcTemplate(new DriverManagerDataSource(url,"sa","")),mapper);assertEquals(p,reopened.get(1,id(p)));}
 @Test void futureModuleCanBeRefined()throws Exception{var p=s.create(1,body("{\"title\":\"复习\",\"goal\":\"数据库\",\"modules\":[{\"title\":\"事务\",\"tasks\":[{\"title\":\"例子\",\"minutes\":20}]},{\"title\":\"索引\",\"tasks\":[]}]}"));var moduleId=p.path("modules").get(1).path("id").asText();s.updateTask(1,id(p),task(p),body("{\"version\":1,\"status\":\"completed\"}"));var refined=s.addTask(1,id(p),moduleId,body("{\"version\":2,\"title\":\"理解B树\",\"minutes\":15}"));assertEquals("in_progress",refined.path("status").asText());assertEquals(1,refined.path("nextTasks").size());assertThrows(ResponseStatusException.class,()->s.addTask(2,id(p),moduleId,body("{\"version\":3,\"title\":\"越权\"}")));}
 @Test void validSameBudgetAndNegationSafety()throws Exception{var p=create();assertNotNull(s.propose(1,id(p),body("{\"version\":1,\"message\":\"每天30分钟\"}")));assertThrows(ResponseStatusException.class,()->s.propose(1,id(p),body("{\"version\":1,\"message\":\"不要延期\"}")));assertThrows(ResponseStatusException.class,()->s.propose(1,id(p),body("{\"version\":18446744073709551617,\"message\":\"每天30分钟\"}")));}
 @Test void exactConflictPreviewAndDayChangeRequireReproposal()throws Exception{var p=create();var pr=s.propose(1,id(p),body("{\"version\":1,\"message\":\"每天20分钟\",\"deadline\":\"2000-01-01\"}"));assertTrue(pr.path("deferredTasks").size()>0);assertFalse(pr.path("extendedDeadline").asText().isBlank());pr.put("evaluatedDate","2000-01-01");jdbc.update("UPDATE adaptive_plan_proposal SET document_json=? WHERE id=?",pr.toString(),pr.path("id").asText());assertEquals(409,assertThrows(ResponseStatusException.class,()->s.apply(1,id(p),pr.path("id").asText(),body("{\"version\":1,\"resolution\":\"defer\"}"))).getStatusCode().value());}
}